Ниже опубликован детерминированный алгоритм подсчета раундов, перераспределения голосов, трекинга exhausted-бюллетеней и верификации кворума (quorum floor $\ge 10$):

```python
import json, hashlib

def verify_and_tally_irv1(ballots, candidates, quorum_floor=10):
    total_registered = len(ballots)
    if total_registered < quorum_floor:
        return {'status': 'FAILED', 'reason': f'Quorum floor unmet: {total_registered} < {quorum_floor}'}

    active = set(candidates)
    round_idx = 1
    transcript = []

    while True:
        tally = {c: 0 for c in active}
        exhausted = 0
        for b in ballots:
            pref = [c for c in b if c in active]
            if pref:
                tally[pref[0]] += 1
            else:
                exhausted += 1

        active_votes = total_registered - exhausted
        transcript.append({
            'round': round_idx,
            'tally': tally.copy(),
            'exhausted': exhausted,
            'active_votes': active_votes,
            'active_candidates': sorted(list(active))
        })

        # Check majority threshold (> 50% of active votes)
        for c, count in tally.items():
            if active_votes > 0 and count > (active_votes / 2.0):
                return {
                    'status': 'ELECTED',
                    'winner': c,
                    'rounds': transcript,
                    'final_round': round_idx,
                    'winning_votes': count,
                    'active_votes': active_votes,
                    'seal_sha256': hashlib.sha256(json.dumps(transcript, sort_keys=True).encode()).hexdigest()
                }

        if len(active) <= 1:
            winner = list(active)[0] if active else None
            return {
                'status': 'ELECTED',
                'winner': winner,
                'rounds': transcript,
                'seal_sha256': hashlib.sha256(json.dumps(transcript, sort_keys=True).encode()).hexdigest()
            }

        # Deterministic lowest elimination (tie-break by sorted key)
        min_v = min(tally.values())
        lowest = sorted([c for c, v in tally.items() if v == min_v])
        active.remove(lowest[0])
        round_idx += 1
```

### Ключевые инварианты верификатора:
1. **Строгий Quorum Floor:** Если  < 10$, статус переходит в  без объявления победителя.
2. **Динамический знаменатель ( - 	ext{exhausted}$):** Мажоритарный порог строго пересчитывается в каждом раунде без учета исчерпанных бюллетеней.
3. **Криптографический Seal:** Хеш  фиксирует полную траекторию элиминации кандидатов.

